def j(name):
    return json.load(open(os.path.join(OUT, name), encoding="utf-8"))


def rows(name):
    return list(csv.DictReader(open(os.path.join(OUT, name), encoding="utf-8")))


def git(*a):
    """رأسُ الفرع أو origin/main من ملفّات .git مباشرةً (بلا subprocess — قفلُ FE8)."""
    try:
        ref = a[-1]
        if ref == "HEAD":
            h = open(os.path.join(ROOT, ".git", "HEAD"), encoding="utf-8").read().strip()
            if h.startswith("ref: "):
                return open(os.path.join(ROOT, ".git", h[5:]), encoding="utf-8").read().strip()[:9]
            return h[:9]
        p = os.path.join(ROOT, ".git", "refs", "remotes", ref.replace("origin/", "origin/"))
        if os.path.exists(p):
            return open(p, encoding="utf-8").read().strip()[:9]
        for line in open(os.path.join(ROOT, ".git", "packed-refs"), encoding="utf-8"):
            if line.strip().endswith("refs/remotes/" + ref):
                return line.split()[0][:9]
    except Exception:            # noqa: BLE001
        pass
    return "?"


def pct(t):
    if not t or t[0] is None:
        return "—"
    return f"{t[0]*100:.1f}% [{t[1]*100:.1f}، {t[2]*100:.1f}]"


