         f"- المؤلّف: " + " · ".join(f"{k} {v}" for k, v in cp["inventory_author"].items()) + " (F = فيصل · EDU/TP/THIRD_PARTY = غيرُه · U = المستخدم).",
         f"- التكرار: {A['duplicates']}.", "",
         "## ② فحصُ العين في هذه المهمّة (تغطيةٌ صادقة)",
